            </div>
          )}
        </div>
      )}
      {v === "table" && <Table cols={["", ...b.sides.map((s) => s.label)]} rows={b.metrics.map((m) => [m.label, ...b.sides.map((s) => fmt(s.values[m.key] ?? 0))])} />}
