    if (!on) return;
    const tick = () => {
      const h = hostRef.current;
      const now = Date.now();
      let mem: WatchMemory = { spoken: [], last: {} };
      try { mem = JSON.parse(store.get("thunai-watch") ?? "") as WatchMemory; } catch { /* first run */ }
      const signals: Signal[] = [];
      const bell = (h.ov.bell ?? []) as { id: string; sev?: string; title?: string; type?: string; zone_name?: string | null }[];
      if (!seenBell.current) seenBell.current = new Set(bell.map((b) => String(b.id)));
      for (const b of bell) {
        const isNew = !seenBell.current.has(String(b.id));
        seenBell.current.add(String(b.id));
        if (!isNew || b.sev !== "Severe") continue;
        const where = b.zone_name ?? "Chennai";
        signals.push({ key: `bell:${b.id}`, kind: "severe", lifeSafety: false, impact: 1, urgency: 1, confidence: 0.9, novelty: 1, actionability: 0.8, level: 1,
          text: { en: `New severe incident: ${b.type ?? "incident"}, ${where}.`, ta: `புதிய கடுமையான நிகழ்வு: ${b.type ?? ""}, ${where}.` } }); // never the title: titles can be a citizen's own words
      }
      for (const r of memoryRef.current?.reminders ?? []) {
        if (r.done || Date.parse(r.at) > now) continue;
        signals.push({ key: `rem:${r.id}`, kind: "reminder", lifeSafety: false, impact: 0.8, urgency: 1, confidence: 1, novelty: 1, actionability: 1, level: 1,
          text: { en: line("reminderDue", "en", { text: r.text }), ta: line("reminderDue", "ta", { text: r.text }) } });
        void changeMemory({ op: "reminderDone", id: r.id });
      }
      const today = new Date().toDateString();
      const hr = new Date().getHours();
      if (hr >= 7 && hr < 10 && store.get("thunai-greeted") !== today) {
        store.set("thunai-greeted", today);
        const counts = (h.ov.severity?.counts ?? {}) as Record<string, number>;
        const g = { severe: counts.Severe ?? 0, alerts: bell.length };
        signals.push({ key: `greet:${today}`, kind: "greeting", lifeSafety: false, impact: 0.8, urgency: 0.9, confidence: 1, novelty: 1, actionability: 0.9, level: 1,
          text: { en: line("greet", "en", g), ta: line("greet", "ta", g) } });
      }
      for (const s of signals.sort((a, b) => band(b).localeCompare(band(a)))) {
        if (watchMaySpeak(s, mem, now, { quiet: outMode === "quiet", lastUserSpeech: lastUserSpeech.current }) && phase !== "listening" && phase !== "acting") {
          mem = watchRemember(s, mem, now);
          store.set("thunai-watch", JSON.stringify(mem));
          earcon("need");
          out(s.text[listenLang], listenLang);
          break;
        }
      }
    };
    const first = setTimeout(tick, 1500);
    const t = setInterval(tick, 60_000);
    return () => { clearTimeout(first); clearInterval(t); };
  }, [on, outMode, listenLang]); // eslint-disable-line react-hooks/exhaustive-deps

  const openTrail = async () => {
    try { const r = await fetch("/api/collector/thunai/audit"); if (r.ok) { setTrail(await r.json()); setPanel("trail"); } } catch { /* offline */ }
  };

  // --------------------------------------------------------------- render --
  if (!mounted) return null;
  const ta = listenLang === "ta";
  const steps = chips.length > 0 && (phase === "acting" || phase === "thinking") ? (
    <div className="th-chips jv-steps">
      {chips.map((c, i) => <span key={c.id} className={`th-chip ${c.state}`}>{c.state === "done" ? "✓ " : c.state === "failed" ? "✕ " : ""}{c.label}{i < chips.length - 1 ? <i>→</i> : null}</span>)}
    </div>
  ) : null;
  const waiting = askOnce || pendingB || tray.length > 0 || steps ? (
    <>
      {steps}
      {askOnce && (
        <div className="th-card" role="dialog" aria-label={askOnce.question}>
          <p>{askOnce.question}</p>
          <div className="row">
            {askOnce.choices.map((c, i) => (
              <button key={i} onClick={() => void pickChoice(askOnce, c)}>{i + 1}. {c.label}</button>
            ))}
          </div>
        </div>
      )}
      {pendingB && (
        <div className="th-card amber" role="dialog" aria-label={pendingB.text}>
          <p>{pendingB.text}</p>
          <div className="row">
            <button className="primary" onClick={() => { const p = pendingB; setPendingB(null); if (p.act) p.act(); else void run(p.steps, p.lang, p.heard, "rules"); }}>{ta ? "ஆம்" : "Yes"}</button>
            <button onClick={() => { setPendingB(null); setPhase("ready"); }}>{ta ? "வேண்டாம்" : "No"}</button>
          </div>
        </div>
      )}
      {tray.length > 0 && (
        <div className="th-tray" role="region" aria-label="Approval tray">
          <header><b>{ta ? "ஒப்புதலுக்காக" : "Waiting for approval"}</b><span>{tray.length}</span></header>
          <ol>{tray.map((d) => <li key={d.incidentId}><b>{d.title}</b><small>{d.to ?? (ta ? "பெறுநர் இல்லை" : "no recipient")}{d.sandbox ? (ta ? " · சோதனை வழி" : " · sandbox") : (ta ? " · பலகையிலிருந்து அனுப்பவும்" : " · send from the panel")}</small></li>)}</ol>
          <p className="hint">{ta ? `"உறுதி ${tray.length}" என்று சொல்லுங்கள்` : `Say "confirm ${tray.length}"`}</p>
          <div className="row">
            <button className="primary" onClick={() => void sendTray(tray.length, listenLang, "tap")}>{ta ? `${tray.length} அனுப்பு` : `Approve and send ${tray.length}`}</button>
            <button onClick={() => { setTray([]); setTrayShownAt(null); setPhase("ready"); }}>{ta ? "நீக்கு" : "Discard"}</button>
          </div>
        </div>
      )}
    </>
  ) : null;
  return createPortal(
    <div className={`thunai${on ? " on" : ""}${mode !== "off" ? " hud-on" : ""}`} data-thunai-ui data-phase={phase} data-no-i18n>
      {pointer.show && (
        <div className={`th-pointer${pointer.ripple ? " ripple" : ""}`} style={{ transform: `translate(${pointer.x}px, ${pointer.y}px)` }} aria-hidden="true">
          <span className="ring" />{pointer.label && <b>{pointer.label}</b>}
        </div>
      )}
      {numbers && numbers.items.map((it) => (
        <span key={it.n} className="th-badge" style={{ left: Math.max(0, it.x - 6), top: Math.max(0, it.y - 8) }} aria-hidden="true">
          {it.n}{numbers.names && it.name ? ` ${it.name.slice(0, 18)}` : ""}
        </span>
      ))}

      {mode !== "off" && (
        <Hud lang={listenLang} coreRef={orbRef} stageOpen={!!stage} onSend={(t) => { via.current = "typed"; void handle(t, 0.95); }} onDismissFirstUse={() => { store.set("jarvis-mode-seen", "1"); hud.set({ firstUse: false }); if (modeRef.current === "on") { setTimeout(() => earcon("open"), 40); openMic(); } }}
          onStop={interrupt} onMute={() => setMode(mode === "muted" ? "on" : "muted")} onClose={() => setMode("off")}>{waiting}</Hud>
      )}

      {on && panel && (
        <aside className="th-panel" aria-label={panel}>
          <header>
            <b>{panel === "memory" ? (ta ? "ஜார்விஸின் நினைவு" : "What Jarvis remembers") : panel === "trail" ? (ta ? "தணிக்கைப் பதிவு" : "Audit trail") : (ta ? "சொல்லக்கூடியவை" : "Things to say")}</b>
            <button aria-label="Close" onClick={() => setPanel(null)}>×</button>
          </header>
          {panel === "memory" && (
            <div className="body">
              {!memory?.notes.length && !memory?.reminders.length && !Object.keys(memory?.habits ?? {}).length && <p className="muted">{ta ? "இன்னும் எதுவும் இல்லை." : "Nothing yet."}</p>}
              {!!memory?.notes.length && <><h4>{ta ? "குறிப்புகள்" : "Notes"}</h4><ul>{memory.notes.map((n) => <li key={n.id}>{n.text}<button onClick={() => void changeMemory({ op: "forget", id: n.id })}>{ta ? "மற" : "Forget"}</button></li>)}</ul></>}
              {!!memory?.reminders.filter((r) => !r.done).length && <><h4>{ta ? "நினைவூட்டல்கள்" : "Reminders"}</h4><ul>{memory.reminders.filter((r) => !r.done).map((r) => <li key={r.id}>{whenOf(r.at)}: {r.text}<button onClick={() => void changeMemory({ op: "forget", id: r.id })}>{ta ? "மற" : "Forget"}</button></li>)}</ul></>}
              {!!Object.keys(memory?.habits ?? {}).length && <><h4>{ta ? "கற்றவை" : "Learned"}</h4><ul>{Object.entries(memory!.habits).map(([k, v]) => <li key={k}>“{k}” → {v} <em>{ta ? "கற்றது" : "learned"}</em><button onClick={() => void changeMemory({ op: "forget", id: k })}>{ta ? "மற" : "Forget"}</button></li>)}</ul></>}
              <button className="danger" onClick={() => void changeMemory({ op: "forget", all: true })}>{ta ? "எல்லாம் மற" : "Forget everything"}</button>
            </div>
          )}
          {panel === "trail" && trail && (
            <div className="body">
              <p className={trail.intact ? "ok" : "bad"}>{trail.intact ? (ta ? "சங்கிலி முழுமையாக உள்ளது." : "Chain intact: no line was changed.") : (ta ? "சங்கிலி உடைந்துள்ளது!" : "Chain broken: a line was changed.")}</p>
              <ol className="trail">{[...trail.lines].reverse().slice(0, 60).map((l, i) => <li key={i}><time>{whenOf(l.at)}</time><span className={`risk r${l.risk}`}>{l.risk}</span>{l.heard ?? "—"}<small>{l.outcome}</small></li>)}</ol>
            </div>
          )}
          {panel === "help" && (
            <div className="body help">
              <p className="muted">{ta ? "\"ஹாய் ஜார்விஸ்\" என்று சொல்லி சாதாரணமாகப் பேசுங்கள். உதாரணங்கள்:" : "Say \"Hi Jarvis\" and just talk. For example:"}</p>
              {(ta ? ["அம்பத்தூர்ல இந்த வாரம் என்ன நடக்குது காட்டு", "Adyar la police complaints mattum kaatu", "அவசரமானவை மட்டும்", "செம்பரம்பாக்கம் ஏரியில் எவ்வளவு தண்ணீர் இருக்கு", "முதல் சம்பவத்தைத் திற", "நாளைக்கு கனமழை, தயார் பண்ணு", "பழையபடி மாத்து"]
                : ["Show me the severe cases", "Read today's news", "Compare Adyar and Ambattur this week", "Top 3 areas with the most rainfall", "Department-wise performance",
                  "Make me a flooding dashboard for this week", "Schools within 1 km of flooding in Adyar", "How has dengue moved this quarter?",
                  "What's happening in Ambattur this week? Only the serious stuff", "Same for Adyar", "Why is Perungudi looking so bad lately?",
                  "Open the top one and draft something for the department", "How full is Chembarambakkam?", "Explain this chart", "We expect heavy rain tonight, get everything ready",
                  "Remind me at 6 to call the SWD engineer", "Go back"]).map((x) => (
                <button key={x} onClick={() => void handle(x, 0.95)}>{x}</button>
              ))}
            </div>
          )}
        </aside>
      )}

      {on && stage && (
        <Stage doc={stage} lang={listenLang} theme={host.theme ?? "light"} busy={stageBusy} reading={reading} narrating={narrating} views={stageViews} pins={pins} geo={geo ?? host.c.geo}
          tray={tray.map((d) => ({ incidentId: d.incidentId, title: d.title, to: d.to, sandbox: d.sandbox }))} brain={stageBrain} filtered={stageFilter} saveAsk={pendingB ? saveAsk : null}
          caption={{ heard: interim || heard, reply: phase === "listening" ? "" : reply, alt: phase === "listening" ? "" : alt, interim: !!interim,
            by: brain && phase !== "thinking" && phase !== "listening" ? (brain.by === "ai" ? `${ta ? "AI" : "Understood by AI"}${brain.model ? ` · ${brain.model.replace(/^.*\//, "").replace(/#\d+$/, "")}` : ""}${brain.ms ? ` · ${(brain.ms / 1000).toFixed(1)} s` : ""}` : brain.by === "instant" ? (ta ? "உடனடி" : "Instant, no model") : (ta ? "விதிகள்" : "Built-in rules")) : null }}
          a={stageActions} />
      )}

    </div>,
    document.body
  );
}

"use client";

import { useEffect, useState } from "react";
import { I } from "@/components/collector/app/icons";
import { SOURCE_KIND, SevChip, fmtShort, fullTitle, type Row } from "@/components/collector/app/lib";
import type { GrievanceDetail } from "@/lib/officer/data";
import { STAGE_INDEX, STEP_LABELS, type Stage } from "@/lib/officer/stages";
import { StageChip } from "./Cards";
import type { Ctx } from "./OfficerApp";

type Report = GrievanceDetail["reports"][number];

/** Received -> In action -> Sent to Collector -> Verified */
function Steps({ stage }: { stage: Stage }) {
  const k = STAGE_INDEX[stage] ?? 0;
  const last = STEP_LABELS.length - 1;
  return (
    <div className="wfs" aria-label={`Stage ${k + 1} of ${STEP_LABELS.length}: ${STEP_LABELS[k]}`}>
      <span className="rail"><i style={{ width: `${(k / last) * 100}%` }} /></span>
      {STEP_LABELS.map((l, ix) => {
        const done = ix < k || k === last;
        return <div key={l} className={done ? "dn" : ix === k ? "cur" : ""}><s>{done ? <I n="check" /> : null}</s>{l}</div>;
      })}
    </div>
  );
}

function ReportBlock({ r, title }: { r: Report; title: string }) {
  return (
    <div>
      <div className="sec-t">{title}</div>
      <div className="rep">
        <q>“{r.remarks}”</q>
        <span className="meta-row"><I n="user" />{r.by} · sent {fmtShort(r.t)}</span>
        {r.returned && <span className="chip sev-high"><I n="alert" />Returned by Collector{r.returned.note ? `: ${r.returned.note}` : ""}</span>}
        {r.verifiedAt && <span className="chip sev-low"><I n="check" />Verified by Collector · {fmtShort(r.verifiedAt)}</span>}
        <div className="ph-grid">
          {r.photos.map((p, k) => (
            <figure key={p}><a href={p} target="_blank" rel="noreferrer" title="Open the full photo"><img src={p} alt={`Site photo ${k + 1}`} loading="lazy" /></a></figure>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * The grievance drawer: the workflow, the completion report, timeline and sources, with
 * the one action the current stage allows. mode "news" shows the news coverage instead.
 */
export function GrievanceDrawer({ id, mode, c, onMode }: { id: string; mode: "off" | "news"; c: Ctx; onMode: (m: "off" | "news") => void }) {
  const [d, setD] = useState<GrievanceDetail | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    let live = true;
    setErr(null);
    fetch(`/api/officer/grievances/${encodeURIComponent(id)}`, { cache: "no-store" })
      .then(async (r) => {
        const j = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(j.error || "Could not load the grievance.");
        if (live) setD(j);
      })
      .catch((e) => live && setErr(e.message));
    return () => { live = false; };
  }, [id, c.reloadKey, retry]);

  const close = <button className="xbtn" onClick={c.closeAll} aria-label="Close"><I n="x" /></button>;
  if (!d || d.grievance.id !== id) {
    return (
      <aside className="odrawer" role="dialog" aria-label="Grievance">
        <div className="odrawer-h">{close}<h2>{err ? "Grievance" : "Loading…"}</h2></div>
        <div className={`o-state${err ? " err" : ""}`}>
          {err ?? "Loading the grievance…"}
          {err && <button className="btn sm plain" onClick={() => setRetry((n) => n + 1)}>Try again</button>}
        </div>
      </aside>
    );
  }

  const g = d.grievance;
  const where = [g.loc, g.zone_name, g.ward ? `Ward ${g.ward}` : null].filter(Boolean).join(", ") || "Chennai";

  if (mode === "news") {
    const news = d.sources.filter((s) => s.kind === "news");
    const outlets = new Set(news.map((s) => s.name).filter(Boolean));
    return (
      <aside className="odrawer" role="dialog" aria-label="News details">
        <div className="odrawer-h">{close}
          <div className="meta-row"><span className="chip chip-src"><I n="news" />News report</span><span>{fmtShort(news[0]?.t ?? g.t)}</span></div>
          <h2>{fullTitle(g)}</h2>
          <div className="meta-row"><I n="pin" />{where} · {c.dept.name}</div>
        </div>
        <div className="odrawer-b">
          {g.summary && <p style={{ margin: 0, color: "var(--text-2)" }}>{g.summary}</p>}
          <div className="dgrid">
            <div><small>Area</small><b>{g.zone_name ?? "Chennai"}</b></div>
            <div><small>Department concerned</small><b>{c.dept.name}</b></div>
            <div><small>Outlets reporting</small><b className="num">{outlets.size || g.outlets}</b></div>
            <div><small>First reported</small><b>{fmtShort(news[0]?.t ?? g.t)}</b></div>
          </div>
          <div>
            <div className="sec-t">Coverage ({news.length})</div>
            {news.map((s, k) => (
              <div key={k} className="osrc">
                <span className="sic t-high"><I n="news" /></span>
                <span style={{ minWidth: 0 }}>
                  <b>{s.name ?? "News outlet"}</b><small>News report · {fmtShort(s.t)}</small>
                  <q>{s.url ? <a href={s.url} target="_blank" rel="noreferrer">{s.note} ↗</a> : s.note}</q>
                </span>
              </div>
            ))}
            {!news.length && <div className="empty">No articles are linked to this grievance.</div>}
          </div>
        </div>
        <div className="odrawer-f"><button className="btn plain" onClick={() => onMode("off")}><I n="tasks" />Open the grievance</button></div>
      </aside>
    );
  }

  const busy = c.busy.has(g.id);
  const lastReturn = d.reports.find((r) => r.returned)?.returned ?? (g.returned ? { note: g.returnNote ?? "", t: g.updated } : null);
  return (
    <aside className="odrawer" role="dialog" aria-label={`Grievance ${g.id}`}>
      <div className="odrawer-h">{close}
        <div className="meta-row"><span className="num" style={{ color: "#fff", fontWeight: 700 }}>{g.id}</span><SevChip s={g.sev} /><StageChip r={g} /></div>
        <h2>{fullTitle(g)}</h2>
        <div className="meta-row"><I n="pin" />{where} · {c.dept.name}</div>
      </div>
      <div className="odrawer-b">
        <Steps stage={g.stage as Stage} />
        {g.returned && lastReturn && (
          <div className="banner" style={{ background: "var(--high-soft)", color: "#8A4A06" }}><I n="refresh" />
            <span><b>Returned by the Collector for rework.</b> {lastReturn.note || "No note was added."} Fix it on site, then complete and send again.</span>
          </div>
        )}
        {d.instructions.length > 0 && (
          <div className="o-instr">
            <div className="sec-t"><I n="send" />From the Collector · {fmtShort(d.instructions[0].t)}</div>
            <b>{d.instructions[0].subject}</b>
            <p>{String(d.instructions[0].body)}</p>
            {d.instructions[0].ref && (
              <small className="o-ref" title="The same reference is at the foot of the email. A message without it, or with another, did not come from District IQ.">
                <I n="checkc" />Genuine · approved by {d.instructions[0].from} · Ref <b translate="no">{d.instructions[0].ref}</b>
              </small>
            )}
          </div>
        )}
        {g.summary && <p style={{ margin: 0, color: "var(--text-2)" }}>{g.summary}</p>}
        <div className="dgrid">
          <div><small>Reported</small><b>{fmtShort(g.t)}</b></div>
          <div><small>First source</small><b>{d.firstSource}</b></div>
          <div><small>Linked complaints</small><b className="num">{g.complaints}</b></div>
          <div><small>Field officer</small><b>{g.officer ?? "—"}</b></div>
        </div>
        {d.reports.map((r, k) => (
          <ReportBlock key={r.id} r={r} title={k === 0 ? `Completion report from ${c.dept.name}` : `Earlier report · ${fmtShort(r.t)}`} />
        ))}
        <div>
          <div className="sec-t">Timeline</div>
          <ul className="vtl">
            {d.timeline.map((s, k) => (
              <li key={k} className={s.kind}><i /><time>{fmtShort(s.t)}</time><span>{s.label}{s.note ? <small>{s.note}</small> : null}</span></li>
            ))}
          </ul>
        </div>
        <div>
          <div className="sec-t">Sources ({d.sources.length})</div>
          {d.sources.map((s, k) => {
            const kind = SOURCE_KIND[s.kind] ?? SOURCE_KIND.grievance;
            return (
              <div key={k} className="osrc">
                <span className={`sic ${kind.tone}`}><I n={kind.ic} /></span>
                <span style={{ minWidth: 0 }}>
                  <b>{s.name ?? s.label}{s.first ? " · first report" : ""}</b>
                  <small>{s.label} · {fmtShort(s.t)}</small>
                  {s.note && <q>{s.url ? <a href={s.url} target="_blank" rel="noreferrer">{s.note} ↗</a> : s.note}</q>}
                </span>
              </div>
            );
          })}
        </div>
      </div>
      <div className="odrawer-f">
        {g.stage === "new" ? (
          <><button className="btn" disabled={busy} onClick={() => c.approve(g)}><I n="check" />Approve</button>
            <span className="hint">Approving moves it to In action and assigns it to {g.officer ?? "the field officer"}.</span></>
        ) : (g.stage === "approved" || g.stage === "action") && g.sev === "Severe" ? (
          <><button className="btn ok" disabled={busy} onClick={() => c.openSend(g)}><I n="send" />Complete &amp; send to Collector</button>
            <span className="hint">Severe: the Collector verifies it. Remarks and photos go to the Collector.</span></>
        ) : g.stage === "approved" || g.stage === "action" || (g.stage === "sent" && g.sev !== "Severe") ? (
          <><button className="btn ok" disabled={busy} onClick={() => c.openSend(g)}><I n="check" />Complete &amp; close</button>
            <span className="hint">You verify this one: your remarks and photos are kept as the record.</span></>
        ) : g.stage === "sent" ? (
          <span className="st st-await" style={{ padding: "8px 12px", display: "inline-flex", gap: 6, alignItems: "center" }}><I n="clock" />Waiting for the Collector&apos;s verification</span>
        ) : (
          <span className="chip sev-low" style={{ padding: "8px 12px" }}><I n="check" />{d.closedByDept ? "Closed by your department" : "Verified by Collector"}</span>
        )}
      </div>
    </aside>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { I } from "@/components/collector/app/icons";
import { SevChip, deptIcon, fmtShort, fullTitle, type Row } from "@/components/collector/app/lib";
import { OFFICER } from "@/lib/officer/departments";
import type { Ctx } from "./OfficerApp";

/** Scales a photo down in the browser (longest side OFFICER.photoMaxPx, JPEG) so reports upload quickly. */
async function shrink(file: File): Promise<Blob> {
  const url = URL.createObjectURL(file);
  try {
    const img = await new Promise<HTMLImageElement>((resolve, reject) => {
      const i = new Image();
      i.onload = () => resolve(i);
      i.onerror = reject;
      i.src = url;
    });
    const sc = Math.min(1, OFFICER.photoMaxPx / Math.max(img.naturalWidth, img.naturalHeight));
    const cv = document.createElement("canvas");
    cv.width = Math.round(img.naturalWidth * sc);
    cv.height = Math.round(img.naturalHeight * sc);
    cv.getContext("2d")!.drawImage(img, 0, 0, cv.width, cv.height);
    const blob = await new Promise<Blob | null>((resolve) => cv.toBlob(resolve, "image/jpeg", 0.82));
    return blob ?? file;
  } catch {
    return file; // the server checks the file type and says so if it cannot be used
  } finally {
    URL.revokeObjectURL(url);
  }
}

/**
 * Completion report: what was done, with photos of the finished work. A severe grievance goes to the Collector for
 * verification; any other is closed by the department, and the report is kept as its record.
 */
export function SendReport({ row, c, onSent }: { row: Row; c: Ctx; onSent: () => void }) {
  const toCollector = row.sev === "Severe";
  const [remarks, setRemarks] = useState("");
  const [photos, setPhotos] = useState<{ blob: Blob; url: string }[]>([]);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [over, setOver] = useState(false);
  const urls = useRef<string[]>([]);
  useEffect(() => () => urls.current.forEach((u) => URL.revokeObjectURL(u)), []);

  const add = async (files: File[]) => {
    const imgs = files.filter((f) => f.type.startsWith("image/"));
    if (!imgs.length) { setErr("Choose image files (JPG or PNG)."); return; }
    const room = OFFICER.maxPhotos - photos.length;
    const added: { blob: Blob; url: string }[] = [];
    for (const f of imgs.slice(0, Math.max(0, room))) {
      const blob = await shrink(f);
      const url = URL.createObjectURL(blob);
      urls.current.push(url);
      added.push({ blob, url });
    }
    setPhotos((p) => [...p, ...added]);
    setErr(imgs.length > room ? `At most ${OFFICER.maxPhotos} photos can be attached.` : "");
  };

  const send = async () => {
    const text = remarks.trim();
    if (text.length < OFFICER.minRemarks) { setErr("Write remarks describing the work done."); return; }
    if (!photos.length) { setErr("Attach at least one photo of the completed work."); return; }
    setBusy(true);
    setErr("");
    const fd = new FormData();
    fd.append("remarks", text);
    fd.append("step", toCollector ? "send" : "close");
    photos.forEach((p, k) => fd.append("photos", p.blob, `photo-${k + 1}.jpg`));
    try {
      const r = await fetch(`/api/officer/grievances/${encodeURIComponent(row.id)}/report`, { method: "POST", body: fd });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "Could not send the report.");
      onSent();
    } catch (e: any) {
      setErr(e.message);
      setBusy(false);
    }
  };

  return (
    <div className="osend">
      <div className="rep" style={{ flexDirection: "row", alignItems: "center", gap: 12 }}>
        <span className="bic t-info"><I n={deptIcon(c.dept.code)} /></span>
        <span style={{ flex: 1, minWidth: 0 }}>
          <b style={{ display: "block" }}>{fullTitle(row)}</b>
          <span className="dim" style={{ fontSize: 12.5 }}>{row.id} · {row.zone_name ?? "Chennai"} · reported {fmtShort(row.t)} · {row.complaints} complaint{row.complaints === 1 ? "" : "s"}</span>
        </span>
        <SevChip s={row.sev} />
      </div>
      <label className="fld">
        <span className="sec-t" style={{ margin: 0 }}>Remarks · what was done</span>
        <textarea value={remarks} onChange={(e) => setRemarks(e.target.value)} placeholder={`e.g. ${c.dept.remarkHint}`} maxLength={OFFICER.maxRemarks} autoFocus />
        <small>{remarks.trim().length}/{OFFICER.maxRemarks}</small>
      </label>
      <div className="fld">
        <span className="sec-t" style={{ margin: 0 }}>Photos of completed work ({photos.length}/{OFFICER.maxPhotos})</span>
        {photos.length > 0 && (
          <div className="ph-grid" style={{ gridTemplateColumns: "repeat(4,minmax(0,1fr))" }}>
            {photos.map((p, k) => (
              <figure key={p.url}>
                <img src={p.url} alt={`Uploaded photo ${k + 1}`} />
                <button className="ph-x" onClick={() => setPhotos((all) => all.filter((x) => x !== p))} aria-label={`Remove photo ${k + 1}`}><I n="x" /></button>
              </figure>
            ))}
          </div>
        )}
        <label className={`odrop${over ? " over" : ""}`}
          onDragOver={(e) => { e.preventDefault(); setOver(true); }} onDragLeave={() => setOver(false)}
          onDrop={(e) => { e.preventDefault(); setOver(false); add([...e.dataTransfer.files]); }}>
          <I n="photo" /><b>Upload site photos</b><small className="dim">JPG or PNG · you can pick several, or drop them here</small>
          <input type="file" accept="image/*" multiple onChange={(e) => { add([...(e.target.files ?? [])]); e.target.value = ""; }} disabled={busy || photos.length >= OFFICER.maxPhotos} />
        </label>
      </div>
      {err && <div className="oerr" role="alert">{err}</div>}
      <div className="osend-f">
        <button className="btn plain" onClick={c.closeAll} disabled={busy}>Cancel</button>
        {!toCollector && <span className="hint" style={{ marginRight: "auto" }}>Not severe: your department verifies and closes it.</span>}
        <button className="btn" onClick={send} disabled={busy}>{busy ? <><I n="refresh" className="spin" />{toCollector ? "Sending…" : "Closing…"}</>
          : toCollector ? <><I n="send" />Send to Collector</> : <><I n="check" />Close as done</>}</button>
      </div>
    </div>
  );
}

