    call(c, "incidents", { scope: scopeArg(s), sort: "sev", status: "open" })
  ]);
  const t = await seriesBlock(c, s, `${subject} over time`);
  const kd = k.data as { cur: Record<string, number>; prev: Record<string, number>; series: Record<string, number[]> };
